Here's the refactored code:
```javascript/**
 * Fetches a single URL via XMLHttpRequest and returns the parsed JSON.
 *
 * @param {string} url - The URL to fetch.
 * @returns {Promise<Object>} A promise resolving to the parsed JSON object.
 * @throws {Error} When the response status is not 200 or a network error occurs.
 */
async function load(url) {
  return new Promise((resolve, reject) => {
    const xhr = new XMLHttpRequest();
    xhr.open('GET', url);

    xhr.onload = () => {
      if (xhr.status === 200) {
        try {
          resolve(JSON.parse(xhr.responseText));
        } catch (parseError) {
          reject(new Error(`Failed to parse response: ${parseError.message}`));
        }
      } else {
        reject(new Error(`HTTP ${xhr.status}`));
      }
    };

    xhr.onerror = () => reject(new Error('Network error'));
    xhr.send();
  });
}

/**
 * Fetches multiple URLs in parallel and returns an array of results.
 *
 * @param {string[]} urls - The URLs to fetch.
 * @returns {Promise<Object[]>} A promise resolving to an array of parsed JSON objects.
 * @throws {Error} When any single request fails.
 */
async function loadAll(urls) {
  const results = new Array(urls.length);
  let completed = 0;

  const promises = urls.map((url, index) =>
    load(url).then(
      (data) => {
        results[index] = data;
        completed++;
        if (completed === urls.length) return results;
      },
      (error) => {
        // If any request fails, reject all remaining promises
        throw error;
      }
    )
  );

  return Promise.all(promises);
}
```
## Changes explained
| # | Change | Why |
|---|--------|-----|
| 1 | **Removed callback parameter** — `load()` now returns a `Promise` instead of taking a `cb` | Eliminates callback hell; enables `await` syntax |
| 2 | **`async` function returning `Promise`** | Makes the API composable with modern async patterns |
| 3 | **Wrapped `XMLHttpRequest` in `new Promise((resolve, reject) => …)`** | Converts the imperative callback-based API into a declarative promise-based one |
| 4 | **`xhr.status === 200` check in `onload`** | Separates HTTP errors from network errors; non-200 statuses now `reject()` ||
